1	package cli
2	
3	import (
4		"fmt"
5		"strings"
6	
7		"github.com/spf13/cobra"
8	)
9	
10	type experimentalCommandInfo struct {
11		Name       string
12		Invocation string
13		Summary    string
14	}
15	
16	var experimentalCommands = []experimentalCommandInfo{
17		{
18			Name:       "review",
19			Invocation: "entire review",
20			Summary:    "Run configured review skills against the current branch",
21		},
22		{
23			Name:       "tour",
24			Invocation: "entire tour",
25			Summary:    "Tour the Entire CLI",
26		},
27	}
28	
29	func newLabsCmd() *cobra.Command {
30		cmd := &cobra.Command{
31			Use:   "labs",
32			Short: "Explore experimental Entire workflows",
33			Long:  labsOverview(),
34			Args: func(cmd *cobra.Command, args []string) error {
35				if len(args) == 0 {
36					return nil
37				}
38				topic := args[0]
39				err := fmt.Errorf("unknown labs topic %q", topic)
40				fmt.Fprintf(cmd.ErrOrStderr(), "%v\n\n%s\n", err, labsTopicHint(topic))
41				return NewSilentError(err)
42			},
43			Run: func(cmd *cobra.Command, _ []string) {
44				fmt.Fprint(cmd.OutOrStdout(), labsOverview())
45			},
46		}
47		return cmd
48	}
49	
50	func labsOverview() string {
51		if len(experimentalCommands) == 0 {
52			return `Labs
53	
54	No experimental commands are available in this build.
55	`
56		}
57	
58		return `Labs
59	
60	These are newer Entire workflows we are actively refining. They are available
61	to try now, but details may change based on feedback.
62	
63	Available experimental commands:
64	` + renderExperimentalCommands(experimentalCommands) + `
65	Try:
66	  entire tour --help
67	  entire review --help
68	`
69	}
70	
71	// labsTopicHint returns the redirect string shown when the user types
72	// `entire labs <topic>` and topic is not a real labs subcommand. When the
73	// topic matches a known experimental command (e.g. `entire labs review`
74	// when review actually lives at the top level), point at its canonical
75	// invocation instead of leaving the user to guess.
76	func labsTopicHint(topic string) string {
77		for _, info := range experimentalCommands {
78			if info.Name == topic {
79				return fmt.Sprintf("%s lives at `%s`. Run `%s --help` for command-specific help.", info.Name, info.Invocation, info.Invocation)
80			}
81		}
82		return "Run `entire labs` to see available experimental commands."
83	}
84	
85	func renderExperimentalCommands(commands []experimentalCommandInfo) string {
86		width := 16
87		for _, info := range commands {
88			if l := len(info.Invocation); l > width {
89				width = l
90			}
91		}
92		var out strings.Builder
93		for _, info := range commands {
94			out.WriteString("  ")
95			out.WriteString(padRight(info.Invocation, width))
96			out.WriteByte(' ')
97			out.WriteString(info.Summary)
98			out.WriteByte('\n')
99		}
100		return out.String()
101	}
102	
103	func padRight(value string, width int) string {
104		if len(value) >= width {
105			return value
106		}
107		return value + strings.Repeat(" ", width-len(value))
108	}
109

1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9	
10		"charm.land/bubbles/v2/key"
11		"charm.land/bubbles/v2/spinner"
12		tea "charm.land/bubbletea/v2"
13		"charm.land/lipgloss/v2"
14	
15		"github.com/entireio/cli/cmd/entire/cli/tour"
16	)
17	
18	// errTourCancelled is returned when the user presses ctrl+c / q during
19	// the spinner. Surfaced as a normal cancellation, not an error.
20	var errTourCancelled = errors.New("tour cancelled")
21	
22	// tourGenerateResult is the tea.Msg the TUI uses to deliver Generate's
23	// completion back to its Update loop.
24	type tourGenerateResult struct {
25		result *tour.Result
26		err    error
27	}
28	
29	type tourStatusModel struct {
30		ctx      context.Context
31		cancel   context.CancelFunc
32		spinner  spinner.Model
33		styles   tourStatusStyles
34		title    string
35		subtitle string
36		run      func(context.Context) (*tour.Result, error)
37		out      tourGenerateResult
38	}
39	
40	type tourStatusStyles struct {
41		title    lipgloss.Style
42		subtitle lipgloss.Style
43		footer   lipgloss.Style
44		spinner  lipgloss.Style
45	}
46	
47	// runTourTUI runs the spinner program while Generate executes and returns
48	// Generate's result (or the cancellation error). The caller decides what to
49	// do with the markdown.
50	//
51	// Overridable for tests: tests assign a stub that returns a synthetic
52	// result without launching a real bubbletea program.
53	var runTourTUI = defaultRunTourTUI
54	
55	func defaultRunTourTUI(ctx context.Context, w io.Writer, title, subtitle string, run func(context.Context) (*tour.Result, error)) (*tour.Result, error) {
56		runCtx, cancel := context.WithCancel(ctx)
57		defer cancel()
58	
59		model := newTourStatusModel(w, title, subtitle, run)
60		model.ctx = runCtx
61		model.cancel = cancel
62	
63		program := tea.NewProgram(model, tea.WithOutput(w))
64		finalModel, err := program.Run()
65		if err != nil {
66			return nil, fmt.Errorf("run tour tui: %w", err)
67		}
68	
69		finished, ok := finalModel.(tourStatusModel)
70		if !ok {
71			return nil, errors.New("unexpected tour loading state")
72		}
73		clearTourInlineView(w, finished.View().Content)
74		if finished.out.err != nil {
75			return nil, finished.out.err
76		}
77		return finished.out.result, nil
78	}
79	
80	func newTourStatusModel(w io.Writer, title, subtitle string, run func(context.Context) (*tour.Result, error)) tourStatusModel {
81		ss := newStatusStyles(w)
82		styles := newTourStatusStyles(ss)
83		sp := spinner.New(spinner.WithSpinner(spinner.MiniDot))
84		if ss.colorEnabled {
85			sp.Style = styles.spinner
86		}
87		return tourStatusModel{
88			spinner:  sp,
89			styles:   styles,
90			title:    title,
91			subtitle: subtitle,
92			run:      run,
93		}
94	}
95	
96	func newTourStatusStyles(ss statusStyles) tourStatusStyles {
97		styles := tourStatusStyles{
98			title:    lipgloss.NewStyle().Bold(true),
99			subtitle: lipgloss.NewStyle(),
100			footer:   lipgloss.NewStyle(),
101			spinner:  lipgloss.NewStyle().Bold(true),
102		}
103		if !ss.colorEnabled {
104			return styles
105		}
106		styles.title = styles.title.Foreground(lipgloss.Color("#fb923c"))
107		styles.subtitle = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
108		styles.footer = lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
109		styles.spinner = lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")).Bold(true)
110		return styles
111	}
112	
113	func (m tourStatusModel) Init() tea.Cmd {
114		return tea.Batch(m.spinner.Tick, m.runGenerate())
115	}
116	
117	func (m tourStatusModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
118		switch msg := msg.(type) {
119		case tea.WindowSizeMsg:
120			// View doesn't depend on terminal width — the status card lives
121			// inline at a fixed-ish width — but we still drain the message
122			// so bubbletea isn't queueing it indefinitely.
123			_ = msg
124			return m, nil
125		case spinner.TickMsg:
126			var cmd tea.Cmd
127			m.spinner, cmd = m.spinner.Update(msg)
128			return m, cmd
129		case tourGenerateResult:
130			m.out = msg
131			return m, tea.Quit
132		case tea.KeyPressMsg:
133			if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
134				if m.cancel != nil {
135					m.cancel()
136				}
137				m.out.err = errTourCancelled
138				return m, tea.Quit
139			}
140		}
141		return m, nil
142	}
143	
144	func (m tourStatusModel) View() tea.View {
145		lines := []string{
146			m.styles.spinner.Render(m.spinner.View()) + " " + m.styles.title.Render(m.title),
147		}
148		if m.subtitle != "" {
149			lines = append(lines, m.styles.subtitle.Render(m.subtitle))
150		}
151		lines = append(lines, "", m.styles.footer.Render("Press ctrl+c to cancel"))
152		return tea.NewView("\n" + strings.Join(lines, "\n"))
153	}
154	
155	func (m tourStatusModel) runGenerate() tea.Cmd {
156		return func() tea.Msg {
157			result, err := m.run(m.ctx)
158			return tourGenerateResult{result: result, err: err}
159		}
160	}
161	
162	func clearTourInlineView(w io.Writer, view string) {
163		lineCount := strings.Count(view, "\n") + 1
164		if view == "" {
165			return
166		}
167		for range lineCount {
168			_, _ = io.WriteString(w, "\x1b[1A\x1b[2K\r") //nolint:errcheck // terminal escape sequence, write errors are ignorable here
169		}
170	}
171

