9	func TestLabsCmd_PrintsExperimentalCommandList(t *testing.T) {
10		t.Parallel()
11	
12		root := NewRootCmd()
13		var out bytes.Buffer
14		root.SetOut(&out)
15		root.SetErr(&bytes.Buffer{})
16		root.SetArgs([]string{"labs"})
17	
18		if err := root.Execute(); err != nil {
19			t.Fatalf("entire labs failed: %v", err)
20		}
21		got := out.String()
22		for _, want := range []string{
23			"Labs",
24			"newer Entire workflows",
25			"Available experimental commands",
26			"entire review",
27			"entire review --help",
28		} {
29			if !strings.Contains(got, want) {
30				t.Fatalf("entire labs output missing %q:\n%s", want, got)
31			}
32		}
33	}
