36		t.Parallel()
37	
38		root := NewRootCmd()
39		var out bytes.Buffer
40		root.SetOut(&out)
41		root.SetErr(&bytes.Buffer{})
42		root.SetArgs([]string{"labs", "--help"})
43	
44		if err := root.Execute(); err != nil {
45			t.Fatalf("entire labs --help failed: %v", err)
46		}
47		got := out.String()
48		for _, want := range []string{"Labs", "entire review"} {
49			if !strings.Contains(got, want) {
50				t.Fatalf("entire labs --help output missing %q:\n%s", want, got)
51			}
52		}
53	}
