55	func TestLabsCmd_RejectsTopicWithoutRunningIt(t *testing.T) {
56		t.Parallel()
57	
58		root := NewRootCmd()
59		var out, errOut bytes.Buffer
60		root.SetOut(&out)
61		root.SetErr(&errOut)
62		root.SetArgs([]string{"labs", "review"})
63	
64		err := root.Execute()
65		if err == nil {
66			t.Fatal("entire labs review should return an error")
67		}
68		if !strings.Contains(err.Error(), "unknown labs topic") {
69			t.Fatalf("error should mention unknown labs topic, got: %v", err)
70		}
71		if !strings.Contains(errOut.String(), "entire review --help") {
72			t.Fatalf("stderr should point to canonical review help, got:\n%s", errOut.String())
73		}
74		if strings.Contains(out.String(), "Run the review skills configured") {
75			t.Fatalf("entire labs review should not run or show review help, got stdout:\n%s", out.String())
76		}
77	}
