100	func TestLabsRegistryCommandsExistAtCanonicalPaths(t *testing.T) {
101		t.Parallel()
102	
103		root := NewRootCmd()
104		for _, info := range experimentalCommands {
105			// Invocation has the form "entire <segments...>"; cobra's Find
106			// takes the path after "entire". Splitting on whitespace handles
107			// both top-level commands ("entire review", "entire tour") and
108			// any future subcommand-shaped entries.
109			segments := strings.Fields(strings.TrimPrefix(info.Invocation, "entire "))
110			cmd, _, err := root.Find(segments)
111			if err != nil {
112				t.Fatalf("labs command %q should exist at canonical path %q: %v", info.Name, info.Invocation, err)
113			}
114			if cmd == nil {
115				t.Fatalf("labs command %q resolved to nil command", info.Name)
116			}
117			if cmd.Name() != info.Name {
118				t.Fatalf("labs command %q resolved to %q at path %q", info.Name, cmd.Name(), info.Invocation)
119			}
120		}
121	}
