8	
9	func TestDiscover_StripsHiddenAndDeprecated(t *testing.T) {
10		t.Parallel()
11		root := &cobra.Command{Use: "entire", Short: "root"}
12		root.AddCommand(&cobra.Command{Use: "enable", Short: "enable entire"})
13		root.AddCommand(&cobra.Command{Use: "internal-thing", Short: "private", Hidden: true})
14		root.AddCommand(&cobra.Command{Use: "old", Short: "old", Deprecated: "use new"})
15		root.AddCommand(&cobra.Command{Use: "completion", Short: "shell completion"})
16	
17		surface := Discover(root)
18	
19		got := childNames(surface.Root)
20		want := []string{"enable"}
21		if !equalStrings(got, want) {
22			t.Fatalf("Discover() child names = %v, want %v", got, want)
23		}
24	}
25	
26	func TestDiscover_RecursesIntoSubcommands(t *testing.T) {
27		t.Parallel()
28		root := &cobra.Command{Use: "entire"}
29		checkpoint := &cobra.Command{Use: "checkpoint", Short: "checkpoint group"}
30		checkpoint.AddCommand(&cobra.Command{Use: "list", Short: "list checkpoints"})
31		checkpoint.AddCommand(&cobra.Command{Use: "search", Short: "search checkpoints"})
32		root.AddCommand(checkpoint)
33	
34		surface := Discover(root)
35	
36		cp := findChildOrFail(t, surface.Root, "checkpoint")
37		got := childNames(*cp)
38		want := []string{"list", "search"}
39		if !equalStrings(got, want) {
40			t.Fatalf("checkpoint child names = %v, want %v", got, want)
41		}
42		if cp.Path != "entire checkpoint" {
43			t.Errorf("checkpoint.Path = %q, want %q", cp.Path, "entire checkpoint")
44		}
45	}
46	
47	func TestTrimDescription_KeepsFirstParagraph(t *testing.T) {
48		t.Parallel()
49		long := "First paragraph that explains the command.\n\nSecond paragraph with examples and details that should be omitted from the tour."
50		got := trimDescription(long)
51		want := "First paragraph that explains the command."
52		if got != want {
53			t.Errorf("trimDescription = %q, want %q", got, want)
54		}
55	}
56	
57	func childNames(node CommandNode) []string {
58		out := make([]string, 0, len(node.Subcommands))
59		for _, sub := range node.Subcommands {
60			out = append(out, sub.Name)
61		}
62		return out
63	}
64	
65	func findChildOrFail(t *testing.T, node CommandNode, name string) *CommandNode {
66		t.Helper()
67		for i := range node.Subcommands {
68			if node.Subcommands[i].Name == name {
69				return &node.Subcommands[i]
70			}
71		}
72		t.Fatalf("missing subcommand %q under %q", name, node.Name)
73		return nil
74	}
75	
76	func equalStrings(a, b []string) bool {
77		if len(a) != len(b) {
78			return false
79		}
80		for i := range a {
81			if a[i] != b[i] {
82				return false
83			}
84		}
85		return true
86	}
