		"|\x1b\\][^\x07\x1b]*(?:\x07|\x1b\\\\)" + // OSC: ESC ] ... BEL or ESC \
		"|\x1b[@-Z\\\\-_]" + // other ESC sequences
		"|[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]" + // C0 controls excl. \t \n \r, plus DEL
		"|[-]", // C1 controls
)

